-- Hyprland Lua config. Docs: https://wiki.hypr.land/Configuring/Start/
-- Opinions borrowed from Omarchy 4.x (https://github.com/basecamp/omarchy),
-- ported to plain hl.* calls with no Omarchy scripts required.
-- Stock example config is saved as hyprland.lua.stock.bak.

-- Shared program choices, read by the modules below.
programs = {
  terminal    = "ghostty",
  browser     = "chromium",
  fileManager = "nautilus",
  menu        = "hyprlauncher",
}

require("conf.monitors")
require("conf.env")
require("conf.looknfeel")

-- Theme colors (borders), generated by theme-apply; skipped until a theme is applied.
pcall(dofile, os.getenv("HOME") .. "/.local/state/quickshell/theme/hyprland.lua")

require("conf.input")
require("conf.windows")
require("conf.bindings")
require("conf.autostart")
